package br.edu.scoa.academico.aplicacao.matriculas;
import br.edu.scoa.academico.aplicacao.identidade.*;import br.edu.scoa.academico.dominio.matriculas.*;import br.edu.scoa.academico.dominio.turmas.*;import java.time.*;import java.util.*;
public final class GestaoInscricoes {private final ServicoIdentidade identidade;private final Sessao sessao;private final RepositorioMatriculas matriculas;private final RepositorioInscricoes inscricoes;private final ConsultaElegibilidade elegibilidade;private final Clock relogio;public GestaoInscricoes(ServicoIdentidade i,Sessao s,RepositorioMatriculas m,RepositorioInscricoes r,ConsultaElegibilidade e,Clock c){identidade=i;sessao=s;matriculas=m;inscricoes=r;elegibilidade=e;relogio=c;}private long autor(){if(!identidade.coordenador(sessao))throw new FalhaIdentidade(FalhaIdentidade.Codigo.NAO_AUTORIZADO);return sessao.usuarioId();}public InscricaoTurma inscrever(long matriculaId,long turmaId,UUID op){long a=autor();var m=matriculas.consultar(matriculaId).orElseThrow(()->new FalhaMatricula(FalhaMatricula.Codigo.NAO_ENCONTRADO));if(m.situacao()!=SituacaoMatricula.ATIVA)throw new FalhaMatricula(FalhaMatricula.Codigo.MATRICULA_NAO_ATIVA);var r=elegibilidade.verificar(m.alunoId(),m.matrizId(),turmaId);if(!r.disponivel())throw new FalhaMatricula(FalhaMatricula.Codigo.INTEGRACAO_INDISPONIVEL);if(r.possuiImpedimento()||!r.documentosAprovados())throw new FalhaMatricula(FalhaMatricula.Codigo.IMPEDIMENTO_ATIVO);if(!r.preRequisitosAtendidos())throw new FalhaMatricula(FalhaMatricula.Codigo.PRE_REQUISITO_NAO_ATENDIDO);return inscricoes.inscrever(new InscricaoTurma(0,matriculaId,turmaId,SituacaoInscricao.ATIVA,relogio.instant(),0),op,a,relogio.instant());}}
